function constantTimeHexEqual(hexA, hexB) {
  if (!/^[0-9a-f]{64}$/i.test(hexA) || !/^[0-9a-f]{64}$/i.test(hexB)) return false;
  const a = hexA.toLowerCase();
  const b = hexB.toLowerCase();
  try {
    const { timingSafeEqual } = require('node:crypto');
    return timingSafeEqual(Buffer.from(a, 'hex'), Buffer.from(b, 'hex'));
  } catch {
    let diff = 0;
    for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
    return diff === 0;
  }
}
const GOOGLE_MAPS_URL_RE = /^https:\/\/(?:(?:search|www|maps)\.google\.(?:com|[a-z]{2,3}(?:\.[a-z]{2})?)|maps\.app\.goo\.gl)\//i;
const item = $input.first().json;
const headers = item.headers || {};
const rawKey = String(headers['x-autonomous-key'] || headers['X-Autonomous-Key'] || '').trim();
if (!rawKey || !constantTimeHexEqual(String(item.providedKeySha256 || ''), String(item.expectedKeySha256 || ''))) {
  throw new Error('Acceso no autorizado al webhook de configuración review-booster');
}
const payload = item.body && typeof item.body === 'object' ? item.body : item;
const clientSlug = String(payload.client_slug || '').trim();
if (!/^[a-z0-9-]+$/i.test(clientSlug)) {
  throw new Error('client_slug inválido en configuración review-booster');
}
const rawReviewUrl = payload.review_url ? String(payload.review_url).trim() : '';
if (rawReviewUrl && !GOOGLE_MAPS_URL_RE.test(rawReviewUrl)) {
  throw new Error('review_url rechazada: solo se permiten hosts oficiales de Google Maps por HTTPS');
}
const rawPlaceId = payload.maps_place_id ? String(payload.maps_place_id).trim() : '';
const safePlaceId = /^[A-Za-z0-9_-]{10,200}$/.test(rawPlaceId) ? rawPlaceId : null;
return [{
  json: {
    client_slug: clientSlug,
    validatedConfig: {
      workflow_id: '03-review-booster',
      client_slug: clientSlug,
      provider_name: String(payload.provider_name || '').trim(),
      specialty: String(payload.specialty || '').trim(),
      maps_place_id: safePlaceId,
      review_url: rawReviewUrl || null,
      compliance: {
        ley_25326: true,
        require_opt_in: true,
        respect_opt_out_keyword: 'baja',
        no_incentives_policy: true,
        idempotent_reminder_type: 'review_5star'
      }
    }
  }
}];

const GOOGLE_MAPS_URL_RE = /^https:\/\/(?:(?:search|www|maps)\.google\.(?:com|[a-z]{2,3}(?:\.[a-z]{2})?)|maps\.app\.goo\.gl)\//i;
const rows = $('Postgres Turnos Concretados Elegibles').all();
const configs = $input.all();
return rows.map((item, idx) => {
  const row = item.json;
  const rawCfg = configs[idx]?.json?.boosterConfigRaw;
  let cfg = {};
  if (typeof rawCfg === 'string' && rawCfg.trim()) {
    try { cfg = JSON.parse(rawCfg); } catch {}
  } else if (rawCfg && typeof rawCfg === 'object') {
    cfg = rawCfg;
  }
  const placeId = String(cfg.maps_place_id || row.maps_place_id || '').trim();
  const providerName = String(cfg.provider_name || row.provider_name || row.client_slug || 'nuestro consultorio').trim();
  const specialty = String(cfg.specialty || row.specialty || '').trim();
  const firstName = String(row.patient_first_name || '').trim();
  const cfgUrl = String(cfg.review_url || '').trim();
  const reviewUrl = /^[A-Za-z0-9_-]{10,200}$/.test(placeId)
    ? `https://search.google.com/local/writereview?placeid=${encodeURIComponent(placeId)}`
    : GOOGLE_MAPS_URL_RE.test(cfgUrl)
      ? cfgUrl
      : `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(providerName)}`;
  const greeting = firstName ? `Hola ${firstName}` : 'Hola';
  const specialtyText = specialty ? ` (${specialty})` : '';
  const messageText = `${greeting}, ¿cómo estás? Te escribimos de parte de ${providerName}${specialtyText} para agradecerte por la consulta de hoy. Si podés compartir en 30 segundos cómo fue tu experiencia en Google Maps, ayudás a otros pacientes a encontrarnos con tranquilidad: ${reviewUrl} Si preferís no recibir este tipo de avisos, respondé "baja" y lo desactivamos de inmediato.`;
  return {
    json: {
      workflow_id: '03-review-booster',
      idempotent_reminder_type: 'review_5star',
      appointment_id: row.id,
      client_slug: row.client_slug,
      provider_name: providerName,
      maps_place_id: placeId || null,
      to: row.patient_phone_e164,
      review_url: reviewUrl,
      messageText,
      telemetry_event: {
        client_slug: row.client_slug,
        event_type: 'review_invite_sent',
        count_delta: 1
      }
    }
  };
});
